You will find these "shortened"/protected download links when linking the "Spoiler" buttons.
The script that is doing this is easily visible in the source code of the page:
<details><summary>Details</summary>
<p>

```
<script type="text/javascript">
   /*Agregar los dominios que se desean omitir en el acortador*/
   const excludeDomains = ['fiuxy2.co'];
   
   function DOM_Ready(fn) {
     if (document.attachEvent ? document.readyState === "complete" : document.readyState !== "loading") fn();
     else document.addEventListener('DOMContentLoaded', fn);
   }
   DOM_Ready(() => {
     var aList = document.querySelectorAll('a');
     aList.forEach((e) => {
      let isExluded=false;
        excludeDomains.forEach((d) => { if (e.href.indexOf(d) > -1) { isExluded=true; return; } });
      if(isExluded)return;
      e.href = 'https://mega-enlace.com/ext.php?o=' + btoa(rt13(btoa(rt13(e.href + '|fixy'))));
     });
   });
   function rt13(t){return(t+"").replace(/[a-z]/gi,(function(t){return String.fromCharCode(t.charCodeAt(0)+(t.toLowerCase()<"n"?13:-13))}))};
</script>
